local function hashish(v)
    if type(v) == 'number' then return v end
    if type(v) == 'string' then return joaat(v) end
    return nil
end

TattooIndex = {}
for i = 1, #TattooCatalog do
    local t = TattooCatalog[i]
    local ck = hashish(t.collection)
    local ok = hashish(t.overlay)
    if ck and ok then
        TattooIndex[ck .. ':' .. ok] = t
        TattooIndex[(t.collection or ''):lower() .. ':' .. (t.overlay or ''):lower()] = t
    end
end

function TattooLookup(collection, overlay)
    local ck = hashish(collection)
    local ok = hashish(overlay)
    if ck and ok and TattooIndex[ck .. ':' .. ok] then
        return TattooIndex[ck .. ':' .. ok]
    end
    if type(collection) == 'string' and type(overlay) == 'string' then
        return TattooIndex[collection:lower() .. ':' .. overlay:lower()]
    end
    return nil
end
